CREATE TABLE IF NOT EXISTS products (id VARCHAR(100) PRIMARY KEY, payload LONGTEXT NOT NULL, updated_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(36) PRIMARY KEY, reference VARCHAR(40) NOT NULL UNIQUE, checkout_key VARCHAR(36) NOT NULL UNIQUE, payload LONGTEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', payment_status VARCHAR(30) NOT NULL DEFAULT 'unpaid', created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, INDEX orders_date(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(100) PRIMARY KEY, payload LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits (`key` VARCHAR(64) PRIMARY KEY, count INTEGER NOT NULL, expires_at BIGINT NOT NULL, INDEX rate_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_users (email VARCHAR(254) PRIMARY KEY, password_hash VARCHAR(256) NOT NULL, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash VARCHAR(64) PRIMARY KEY, email VARCHAR(254) NOT NULL, expires_at BIGINT NOT NULL, INDEX session_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS uploads (id VARCHAR(80) PRIMARY KEY, content_type VARCHAR(30) NOT NULL, data LONGBLOB NOT NULL, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_users (email VARCHAR(254) PRIMARY KEY, password_hash VARCHAR(256) NOT NULL, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_sessions (token_hash VARCHAR(64) PRIMARY KEY, email VARCHAR(254) NOT NULL, expires_at BIGINT NOT NULL, INDEX customer_session_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
